args.command:
node -e "
import('./src/scheduler.js').then(({runOrder}) => {
  const order = runOrder([{id:'a',priority:'2'},{id:'b',priority:'10'},{id:'c',priority:'1'}]);
  console.log('runOrder result:', JSON.stringify(order));
});
import('./src/parse.js').then(({parseTask}) => {
  const t = parseTask({id:'x', priority:' 10 '});
  console.log('parseTask result:', JSON.stringify(t), 'typeof priority:', typeof t.priority);
});
"

node --input-type=module -e "
import { runOrder } from './src/scheduler.js';
import { parseTask } from './src/parse.js';
const order = runOrder([{id:'a',priority:'2'},{id:'b',priority:'10'},{id:'c',priority:'1'}]);
console.log('runOrder result:', JSON.stringify(order));
const t = parseTask({id:'x', priority:' 10 '});
console.log('parseTask result:', JSON.stringify(t), 'typeof priority:', typeof t.priority);
const bad = parseTask({id:'x', priority:'soon'});
console.log('parseTask(soon) did not throw:', JSON.stringify(bad));
"
